use std::fs
use std::env
use std::process

fn emit(text: string, number: bool, counter: int) -> int {
    let mut n = counter
    if !number {
        print(text)
        return n
    }
    let ends = text.ends_with("\n")
    let lines = text.split("\n")
    let total: int = lines.len() as int
    let mut i: int = 0
    for line in lines {
        i = i + 1
        if i == total && ends {
            break
        }
        if i == total && line == "" {
            break
        }
        n = n + 1
        println("${n:>6}\t${line}")
    }
    n
}

